#ifndef CBLUEPRINT_REGISTRY_H
#define CBLUEPRINT_REGISTRY_H

#include "node.h"

#include <string.h>

/* Fail fast at init: assert every registered descriptor satisfies its
 * pure_kind invariants (see core/validate.c). */
void registry_validate(void);

/* Generated by reflect (generated/registry.c), compiled into core. */
extern node_desc *const REGISTRY_NODES[];
extern const int REGISTRY_NODE_COUNT;
extern const type_desc *const REGISTRY_TYPES[];
extern const int REGISTRY_TYPE_COUNT;

/* Hand-written nodes (core/const_nodes.c), compiled into core. */
extern node_desc *const EXTRA_NODES[];
extern const int EXTRA_NODE_COUNT;

extern node_desc *const FLOW_NODES[];
extern const int FLOW_NODE_COUNT;
extern node_desc NODE_Event, NODE_Branch, NODE_Sequence, NODE_ForLoop, NODE_Delay,
    NODE_PrintString, NODE_GetVariable, NODE_SetVariable, NODE_Self, NODE_CallEvent;

static inline int registry_node_count(void)
{ return REGISTRY_NODE_COUNT + EXTRA_NODE_COUNT + FLOW_NODE_COUNT; }

/* NULL if i is out of range. */
static inline const node_desc *registry_node(int i)
{
    if (i < 0) return NULL;
    if (i < REGISTRY_NODE_COUNT) return REGISTRY_NODES[i];
    i -= REGISTRY_NODE_COUNT;
    if (i < EXTRA_NODE_COUNT) return EXTRA_NODES[i];
    i -= EXTRA_NODE_COUNT;
    if (i >= FLOW_NODE_COUNT) return NULL;
    return FLOW_NODES[i];
}

/* NULL if no node type is named `name`. */
static inline const node_desc *registry_node_by_name(const char *name)
{
    for (int i = 0; i < REGISTRY_NODE_COUNT; i++)
        if (strcmp(REGISTRY_NODES[i]->name, name) == 0)
            return REGISTRY_NODES[i];
    for (int i = 0; i < EXTRA_NODE_COUNT; i++)
        if (strcmp(EXTRA_NODES[i]->name, name) == 0) return EXTRA_NODES[i];
    for (int i = 0; i < FLOW_NODE_COUNT; i++)
        if (strcmp(FLOW_NODES[i]->name, name) == 0) return FLOW_NODES[i];
    return NULL;
}

#endif
